#!/usr/bin/env bash
# Platform-agnostic build gate for the bdmv-web workspace.
#
# This script is the hand-off point for a future CI pipeline (decision D1=A: the
# pipeline itself - triggers, caches, credentials - is a separate change). It is
# intentionally free of any provider-specific configuration.
#
# It does NOT verify the integrity of the large binary fixtures under test-data/.
# Those files are fetched or generated by the scripts in scripts/*.mjs, and their
# byte-level integrity is out of scope for this gate.
#
# Usage: bash scripts/ci.sh
#        PNPM=pnpm bash scripts/ci.sh     # only if pnpm is installed globally
set -euo pipefail

cd "$(dirname "$0")/.."

run() {
  local label="$1"
  shift
  printf '\n=== %s ===\n$ %s\n' "$label" "$*"
  local started_at ended_at status
  started_at="$(date +%s)"
  set +e
  "$@"
  status=$?
  set -e
  ended_at="$(date +%s)"
  printf '=== %s: exit %d in %ss ===\n' "$label" "$status" "$((ended_at - started_at))"
  if [ "$status" -ne 0 ]; then
    printf 'Gate failed at: %s\n' "$*" >&2
    exit "$status"
  fi
}

# `package.json` pins `packageManager: pnpm@11.25.0`, so `corepack pnpm` selects
# exactly that version. Corepack ships with Node, which means the gate does not
# depend on a globally installed pnpm - and the nested `pnpm` calls that
# `pnpm -r ...` makes inside package scripts resolve through the same shim.
# `PNPM` stays overridable for images that install pnpm themselves.
PNPM_CMD=()
read -r -a PNPM_CMD <<< "${PNPM:-corepack pnpm}"

run "install" "${PNPM_CMD[@]}" install --frozen-lockfile
run "generate:contracts" "${PNPM_CMD[@]}" generate:contracts
run "build" "${PNPM_CMD[@]}" -r build
run "typecheck" "${PNPM_CMD[@]}" -r typecheck
run "test:all" "${PNPM_CMD[@]}" test:all

printf '\nGate passed.\n'
